cd /Users/mike/github/sw-ml-study/demo-decision-model
cat > crates/tdm-trace/src/lib.rs <<'RS'
//! Parsing and validation for the typed decision trace interchange format.
//!
//! A trace is what a decision model's run leaves behind: for every turn, the
//! state that went in, the choices that were offered, the typed decisions that
//! came out, the policy rule that consumed them, and the output that resulted.
//!
//! This crate knows about *decisions*. It does not know about any particular
//! application: label names, policy text, and output strings are data carried in
//! the trace, never types declared here. That is what lets one instrument render
//! a trace from any demo without a line of new Rust.
//!
//! Two invariants are worth naming, because they are the reason the format
//! exists rather than being incidental checks:
//!
//! 1. **There are exactly three decision kinds.** `choice`, `noul`, and `scale`.
//!    A trace claiming a fourth is rejected. The absence of a generation
//!    primitive is the central claim of the project, so the parser enforces it.
//! 2. **Output text must be quoted from a table the trace carries.** Every turn
//!    names a table and an index, and the text must be byte-identical to the
//!    entry found there. A trace whose output was not in its own table is
//!    rejected as [`ValidationError::TextNotInTable`]. This makes the "the model
//!    cannot invent an output" property checkable from the artifact alone,
//!    rather than only by the repository that produced it.

use std::collections::HashSet;

use serde::Deserialize;

const SCHEMA: &str = "sw-ml-study.decision-trace";
const VERSION: u32 = 1;

const MAX_TURNS: usize = 4_096;
const MAX_DECISIONS_PER_TURN: usize = 64;
/// One more than the highest choice cardinality a single decision may offer.
/// Larger candidate sets go through the two-stage path (score, top-k, choose)
/// rather than being presented to one softmax.
const MAX_LABELS: usize = 256;
const MAX_TABLES: usize = 64;
const MAX_TABLE_ENTRIES: usize = 4_096;
const MAX_MEMORIES: usize = 256;
const MAX_FEATURES: usize = 256;
const MAX_TEXT_BYTES: usize = 4_096;

/// Absolute tolerance for a probability sum and for every derived scalar.
const TOLERANCE: f64 = 1e-6;

/// The three decision kinds. There is deliberately no fourth.
pub const KINDS: [&str; 3] = ["choice", "noul", "scale"];

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Trace {
    schema: String,
    version: u32,
    provenance: Provenance,
    /// Which application produced the trace. Free text: a label for the reader
    /// and the instrument's title, never something this crate branches on.
    demo: String,
    /// The bounded output space. Every turn's text is quoted from here.
    tables: Vec<Table>,
    turns: Vec<Turn>,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Provenance {
    producer: String,
    producer_revision: String,
    generated_at: String,
    source_description: String,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Table {
    name: String,
    entries: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Turn {
    index: u32,
    state: State,
    decisions: Vec<Decision>,
    policy: Policy,
    output: Output,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct State {
    /// The unstructured input this turn decided over.
    text: String,
    /// What the encoder actually saw, for display beside the decision.
    #[serde(default)]
    features: Vec<String>,
    /// Structured state the program keeps outside the model.
    #[serde(default)]
    memory: Vec<Memory>,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Memory {
    id: String,
    text: String,
    #[serde(default)]
    tag: String,
    age_turns: u32,
}

/// One typed decision: a distribution over labels, plus the scalars a policy
/// reads. The shape is uniform across all three kinds so that one validator,
/// one schema, and one renderer serve them all; `p` and `expectation` are the
/// only kind-specific fields.
#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Decision {
    kind: String,
    /// The question asked. For a noul this is the proposition.
    question: String,
    labels: Vec<String>,
    probs: Vec<f64>,
    selected: usize,
    confidence: f64,
    margin: f64,
    calibration: Calibration,
    /// Noul only: probability that the proposition holds.
    #[serde(default)]
    p: Option<f64>,
    /// Scale only: the expected level index over ordered labels.
    #[serde(default)]
    expectation: Option<f64>,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Calibration {
    /// `"none"` for a raw model output, or the name of the map applied.
    method: String,
    #[serde(default)]
    t: Option<f64>,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Policy {
    /// The rule as written in the application, for display.
    rule: String,
    /// The branch it selected.
    branch: String,
}

#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Output {
    table: String,
    index: usize,
    text: String,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ValidationError {
    Malformed,
    UnsupportedSchema,
    UnsupportedVersion(u32),
    Budget(&'static str),
    EmptyText(&'static str),
    TextTooLong(&'static str),
    DuplicateTable(String),
    DuplicateMemoryId(String),
    /// A turn index did not increase; traces are ordered.
    TurnOrder(u32),
    /// A decision claimed a kind outside [`KINDS`]. `"generate"` lands here.
    UnknownKind(String),
    /// Labels and probabilities disagreed, or there were none.
    LabelCount(u32),
    /// A probability was negative, or the distribution did not sum to one.
    NotADistribution(u32),
    /// `selected` was out of range for the label set.
    SelectedOutOfRange(u32),
    /// A derived scalar disagreed with the distribution it is derived from.
    DerivedMismatch(&'static str),
    /// A kind-specific field was present on the wrong kind, or missing on its own.
    FieldForWrongKind(&'static str),
    /// The turn named a table the trace does not carry.
    UnknownTable(String),
    /// The turn's index was outside that table.
    IndexOutOfTable(u32),
    /// The output text was not byte-identical to the table entry it cited.
    /// This is the invariant that makes the no-generation claim checkable.
    TextNotInTable(u32),
}

impl Trace {
    /// Parses and validates one complete trace.
    ///
    /// # Errors
    ///
    /// Returns the first error in the documented validation order.
    pub fn parse(source: &str) -> Result<Self, ValidationError> {
        let trace: Self = serde_json::from_str(source).map_err(|_| ValidationError::Malformed)?;
        trace.validate()?;
        Ok(trace)
    }

    #[must_use]
    pub const fn provenance(&self) -> &Provenance {
        &self.provenance
    }

    #[must_use]
    pub fn demo(&self) -> &str {
        &self.demo
    }

    #[must_use]
    pub fn tables(&self) -> &[Table] {
        &self.tables
    }

    #[must_use]
    pub fn turns(&self) -> &[Turn] {
        &self.turns
    }

    fn table(&self, name: &str) -> Option<&Table> {
        self.tables.iter().find(|t| t.name == name)
    }

    fn validate(&self) -> Result<(), ValidationError> {
        if self.schema != SCHEMA {
            return Err(ValidationError::UnsupportedSchema);
        }
        if self.version != VERSION {
            return Err(ValidationError::UnsupportedVersion(self.version));
        }
        validate_provenance(&self.provenance)?;
        bounded_text(&self.demo, "demo")?;
        self.validate_tables()?;
        self.validate_turns()
    }

    fn validate_tables(&self) -> Result<(), ValidationError> {
        if self.tables.len() > MAX_TABLES {
            return Err(ValidationError::Budget("tables"));
        }
        let mut seen = HashSet::new();
        for table in &self.tables {
            bounded_text(&table.name, "table name")?;
            if !seen.insert(table.name.as_str()) {
                return Err(ValidationError::DuplicateTable(table.name.clone()));
            }
            if table.entries.len() > MAX_TABLE_ENTRIES {
                return Err(ValidationError::Budget("table entries"));
            }
            for entry in &table.entries {
                bounded_text(entry, "table entry")?;
            }
        }
        Ok(())
    }

    fn validate_turns(&self) -> Result<(), ValidationError> {
        if self.turns.len() > MAX_TURNS {
            return Err(ValidationError::Budget("turns"));
        }
        let mut previous: Option<u32> = None;
        for turn in &self.turns {
            if let Some(prev) = previous
                && turn.index <= prev
            {
                return Err(ValidationError::TurnOrder(turn.index));
            }
            previous = Some(turn.index);
            validate_state(&turn.state)?;
            if turn.decisions.len() > MAX_DECISIONS_PER_TURN {
                return Err(ValidationError::Budget("decisions per turn"));
            }
            for decision in &turn.decisions {
                validate_decision(decision, turn.index)?;
            }
            bounded_text(&turn.policy.rule, "policy rule")?;
            bounded_text(&turn.policy.branch, "policy branch")?;
            self.validate_output(turn)?;
        }
        Ok(())
    }

    /// The no-generation invariant: a turn's text must be quoted verbatim from a
    /// table the trace itself carries.
    fn validate_output(&self, turn: &Turn) -> Result<(), ValidationError> {
        let Some(table) = self.table(&turn.output.table) else {
            return Err(ValidationError::UnknownTable(turn.output.table.clone()));
        };
        let Some(entry) = table.entries.get(turn.output.index) else {
            return Err(ValidationError::IndexOutOfTable(turn.index));
        };
        if entry.as_bytes() != turn.output.text.as_bytes() {
            return Err(ValidationError::TextNotInTable(turn.index));
        }
        Ok(())
    }
}

fn validate_provenance(p: &Provenance) -> Result<(), ValidationError> {
    bounded_text(&p.producer, "producer")?;
    bounded_text(&p.producer_revision, "producer revision")?;
    bounded_text(&p.generated_at, "generated at")?;
    bounded_text(&p.source_description, "source description")
}

fn validate_state(state: &State) -> Result<(), ValidationError> {
    bounded_text(&state.text, "state text")?;
    if state.features.len() > MAX_FEATURES {
        return Err(ValidationError::Budget("features"));
    }
    for feature in &state.features {
