/// The no-generation invariant: a turn's text must be rebuildable from an entry
/// of a table the trace itself carries, plus the slots it recorded.
pub(crate) fn validate_output(
    output: &Output,
    table: Option<&Table>,
    turn: u32,
) -> Result<(), ValidationError> {
    let Some(table) = table else {
        return Err(ValidationError::UnknownTable(output.table.clone()));
    };
    let Some(entry) = table.entries.get(output.index) else {
        return Err(ValidationError::IndexOutOfTable(turn));
    };
    for slot in &output.slots {
        bounded_text(slot, "output slot")?;
    }
    if entry.matches(PLACEHOLDER).count() != output.slots.len() {
        return Err(ValidationError::SlotCount(turn));
    }
    if render(entry, &output.slots).as_bytes() != output.text.as_bytes() {
        return Err(ValidationError::TextNotInTable(turn));
    }
    Ok(())
}

/// Fills each `{}` in `entry` with the next slot, in order. The caller has
/// already checked that the counts agree.
fn render(entry: &str, slots: &[String]) -> String {
    let mut out = String::with_capacity(entry.len());
    let mut slots = slots.iter();
    let mut rest = entry;
    while let Some(at) = rest.find(PLACEHOLDER) {
        out.push_str(&rest[..at]);
        if let Some(slot) = slots.next() {
            out.push_str(slot);
        }
        rest = &rest[at + PLACEHOLDER.len()..];
    }
    out.push_str(rest);
    out
}

/// Gap between the two largest probabilities; 1 for a single-label set.
fn margin_of(probs: &[f64]) -> f64 {
    if probs.len() < 2 {
        return 1.0;
    }
    let mut first = f64::NEG_INFINITY;
    let mut second = f64::NEG_INFINITY;
    for p in probs {
        if *p > first {
            second = first;
            first = *p;
        } else if *p > second {
            second = *p;
        }
    }
    first - second
}

/// Expected level index over ordered labels.
fn expectation_of(probs: &[f64]) -> f64 {
    let mut total = 0.0;
    for (i, p) in probs.iter().enumerate() {
        #[expect(clippy::cast_precision_loss, reason = "index is bounded by MAX_LABELS")]
        let weight = i as f64;
        total += weight * p;
    }
    total
}

pub(crate) fn bounded_text(text: &str, what: &'static str) -> Result<(), ValidationError> {
    if text.is_empty() {
        return Err(ValidationError::EmptyText(what));
    }
    if text.len() > MAX_TEXT_BYTES {
        return Err(ValidationError::TextTooLong(what));
    }
    Ok(())
}
