//! The exported bundle: weights, featurizer settings, and demo data.

use serde::Deserialize;

const SCHEMA: &str = "sw-ml-study.decision-bundle";
const VERSION: u32 = 1;

#[derive(Clone, Debug, Deserialize)]
pub struct Provenance {
    pub producer: String,
    pub producer_revision: String,
    pub generated_at: String,
    pub source_description: String,
}

/// Everything the browser needs to run one demo. Field names match the JSON
/// the MLPL exporter writes.
#[derive(Clone, Debug, Deserialize)]
pub struct Bundle {
    pub schema: String,
    pub version: u32,
    pub provenance: Provenance,
    pub demo: String,
    pub title: String,
    pub question: String,
    pub labels: Vec<String>,
    pub fallback: String,
    pub threshold: f64,
    pub slots: usize,
    pub width: usize,
    pub dim: usize,
    pub embedding: Vec<f64>,
    pub head: Vec<f64>,
    pub bias: Vec<f64>,
    /// Per label, the canned replies joined by `|`, in label order.
    pub responses: Vec<String>,
    /// Per label, the matcher's keywords joined by spaces, in label order.
    pub keywords: Vec<String>,
    /// Label indices in keyword-priority order.
    pub match_order: Vec<usize>,
    pub parity: Parity,
}

/// Inputs with the numbers MLPL produced for them, so a port can prove itself.
#[derive(Clone, Debug, Deserialize)]
pub struct Parity {
    pub inputs: Vec<String>,
    /// Row-major `[inputs, labels]` probabilities.
    pub probs: Vec<f64>,
    /// The keyword matcher's label index for each input.
    pub matcher: Vec<usize>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum BundleError {
    Malformed(String),
    UnsupportedSchema,
    UnsupportedVersion(u32),
    Shape(&'static str),
}

impl Bundle {
    /// Parses a bundle and checks every array against the shapes it declares.
    ///
    /// # Errors
    ///
    /// Returns the first inconsistency found.
    pub fn parse(source: &str) -> Result<Self, BundleError> {
        let b: Self =
            serde_json::from_str(source).map_err(|e| BundleError::Malformed(e.to_string()))?;
        if b.schema != SCHEMA {
            return Err(BundleError::UnsupportedSchema);
        }
        if b.version != VERSION {
            return Err(BundleError::UnsupportedVersion(b.version));
        }
        b.check_shapes()?;
        Ok(b)
    }

    fn check_shapes(&self) -> Result<(), BundleError> {
        let k = self.labels.len();
        if k == 0 {
            return Err(BundleError::Shape("labels"));
        }
        if self.embedding.len() != self.slots * self.dim {
            return Err(BundleError::Shape("embedding"));
        }
        if self.head.len() != self.dim * k {
            return Err(BundleError::Shape("head"));
        }
        if self.bias.len() != k {
            return Err(BundleError::Shape("bias"));
        }
        if self.responses.len() != k || self.keywords.len() != k {
            return Err(BundleError::Shape("per-label data"));
        }
        if self.match_order.iter().any(|&i| i >= k) || !self.labels.contains(&self.fallback) {
            return Err(BundleError::Shape("matcher"));
        }
        let n = self.parity.inputs.len();
        if self.parity.probs.len() != n * k || self.parity.matcher.len() != n {
            return Err(BundleError::Shape("parity"));
        }
        Ok(())
    }

    /// Index of a label by name.
    #[must_use]
    pub fn label_index(&self, name: &str) -> Option<usize> {
        self.labels.iter().position(|l| l == name)
    }

    /// The canned replies for a label.
    #[must_use]
    pub fn replies(&self, label: usize) -> Vec<&str> {
        self.responses[label].split('|').collect()
    }

    /// Trainable parameters.
    #[must_use]
    pub fn param_count(&self) -> usize {
        self.embedding.len() + self.head.len() + self.bias.len()
    }
}
RS
cat > crates/tdm-model/src/features.rs <<'RS'
//! The featurizer, ported exactly from `lib/text.mlpl`: normalize, split into
//! words, then hash words and adjacent bigrams into a fixed number of slots.
//!
//! Exactness matters more than elegance here. A single character handled
//! differently changes a hash, which changes which embedding row is read, which
//! changes the decision. The parity test is what keeps this honest.

/// The rolling-hash modulus, as in MLPL.
const MODULUS: u64 = 2_147_483_647;

/// Lowercase ASCII letters, keep letters, digits and spaces, delete apostrophes,
/// and turn every other character into a space. Matches `u:text_clean`, which
/// works byte by byte, so non-ASCII bytes also become spaces.
fn clean(s: &str) -> String {
    s.bytes()
        .filter_map(|b| match b {
            b'A'..=b'Z' => Some(char::from(b + 32)),
            b'a'..=b'z' | b'0'..=b'9' | b' ' => Some(char::from(b)),
            b'\'' => None,
            _ => Some(' '),
        })
        .collect()
}

/// The non-empty words of a cleaned string.
#[must_use]
pub fn words(s: &str) -> Vec<String> {
    clean(s).split(' ').filter(|w| !w.is_empty()).map(str::to_owned).collect()
}

/// Base-31 rolling checksum of a string's bytes modulo 2147483647.
#[must_use]
pub fn hash(s: &str) -> u64 {
    s.bytes().fold(7, |h, b| (h * 31 + u64::from(b)) % MODULUS)
}

/// What the model sees for one input.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Features {
    /// Slot ids of the real features (no padding).
    pub slots: Vec<usize>,
    /// The feature text, for display: words first, then `a_b` bigrams.
    pub tokens: Vec<String>,
}

/// Words first, then adjacent bigrams, up to `width` features in all.
#[must_use]
pub fn featurize(text: &str, slots: usize, width: usize) -> Features {
    let ws = words(text);
    let mut tokens: Vec<String> = ws.iter().take(width).cloned().collect();
    for pair in ws.windows(2) {
        if tokens.len() >= width {
            break;
        }
        tokens.push(format!("{}_{}", pair[0], pair[1]));
    }
    #[expect(
        clippy::cast_possible_truncation,
        reason = "a hash modulo a slot count below u32::MAX fits usize on every target"
    )]
    let ids = tokens.iter().map(|t| (hash(t) % slots as u64) as usize).collect();
    Features { slots: ids, tokens }
}
RS
cat > crates/tdm-model/src/matcher.rs <<'RS'
//! The keyword-matcher yardstick, ported from the demo's MLPL: per-label
//! whole-word keyword lists, tried in priority order, first hit wins, else the
//! fallback label. Generic: the lists and the order are bundle data.

use crate::bundle::Bundle;
use crate::features::words;

pub struct KeywordMatcher<'a> {
    bundle: &'a Bundle,
    fallback: usize,
}

impl<'a> KeywordMatcher<'a> {
    #[must_use]
    pub fn new(bundle: &'a Bundle) -> Self {
        let fallback = bundle.label_index(&bundle.fallback).unwrap_or(0);
        Self { bundle, fallback }
    }

    /// The label the keyword list picks for an input.
    #[must_use]
    pub fn classify(&self, text: &str) -> usize {
        let ws = words(text);
        for &label in &self.bundle.match_order {
            let hit = self.bundle.keywords[label]
                .split(' ')
                .filter(|k| !k.is_empty())
                .any(|k| ws.iter().any(|w| w == k));
            if hit {
                return label;
            }
        }
        self.fallback
    }
}
RS
cat > crates/tdm-model/src/model.rs <<'RS'
//! The forward pass: mean of the addressed embedding rows, one linear head,
//! softmax. The same arithmetic as `u:cm_infer` in `lib/choice_model.mlpl`.

use crate::bundle::Bundle;
use crate::features::{Features, featurize};

/// A trained model, ready to decide.
pub struct Model<'a> {
    bundle: &'a Bundle,
}

/// One Choice decision, with what the model saw.
#[derive(Clone, Debug)]
pub struct Decision {
    pub probs: Vec<f64>,
    pub selected: usize,
    pub confidence: f64,
    pub margin: f64,
    pub features: Features,
}

impl<'a> Model<'a> {
    #[must_use]
    pub const fn new(bundle: &'a Bundle) -> Self {
        Self { bundle }
    }

    /// Logits for one input. An input with no features pools to zero, so its
    /// logits are the bias alone, exactly as in MLPL.
    #[must_use]
    pub fn logits(&self, features: &Features) -> Vec<f64> {
        let b = self.bundle;
        let (d, k) = (b.dim, b.labels.len());
        let mut pooled = vec![0.0; d];
        if !features.slots.is_empty() {
            for &slot in &features.slots {
                for (j, p) in pooled.iter_mut().enumerate() {
                    *p += b.embedding[slot * d + j];
                }
            }
            #[expect(clippy::cast_precision_loss, reason = "feature count is at most the width")]
            let n = features.slots.len() as f64;
            for p in &mut pooled {
                *p /= n;
            }
        }
        (0..k)
            .map(|c| b.bias[c] + (0..d).map(|j| pooled[j] * b.head[j * k + c]).sum::<f64>())
            .collect()
    }

    /// Featurize, run the forward pass, and read off the decision.
    #[must_use]
    pub fn decide(&self, text: &str) -> Decision {
        let features = featurize(text, self.bundle.slots, self.bundle.width);
        let probs = softmax(&self.logits(&features));
        let mut order: Vec<usize> = (0..probs.len()).collect();
        order.sort_by(|&a, &b| probs[b].total_cmp(&probs[a]).then(a.cmp(&b)));
        let selected = order[0];
        let second = order.get(1).map_or(0.0, |&i| probs[i]);
        let margin = if probs.len() < 2 { 1.0 } else { probs[selected] - second };
        Decision { confidence: probs[selected], selected, margin, probs, features }
    }
}

fn softmax(logits: &[f64]) -> Vec<f64> {
    let max = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let exps: Vec<f64> = logits.iter().map(|l| (l - max).exp()).collect();
    let total: f64 = exps.iter().sum();
    exps.iter().map(|e| e / total).collect()
}
RS
