            <header>
                <div>
                    <h1>{ &bundle.title }</h1>
                    <p class="sub">{ "a typed decision model chooses every reply; it never writes one" }</p>
                </div>
                <button class={classes!("toggle", tracing.then_some("on"))} onclick={on_toggle}>
